import type { Cache } from '~/cache/core/cache.ts';
import { entityKind, is } from '~/entity.ts';
import type { TypedQueryBuilder } from '~/query-builders/query-builder.ts';
import type { AnyRelations, EmptyRelations } from '~/relations.ts';
import { SelectionProxyHandler } from '~/selection-proxy.ts';
import { type ColumnsSelection, type SQL, sql, type SQLWrapper } from '~/sql/sql.ts';
import { WithSubquery } from '~/subquery.ts';
import type { InferInsertModel, RequiredInsertKeys } from '~/table.ts';
import type { DrizzleTypeError, IsNever, JoinUnion } from '~/utils.ts';
import type { MySqlDialect } from '../dialect.ts';
import {
	MySqlInsertBuilder,
	MySqlSelectBuilder,
	MySqlUpdateBuilder,
	type NoDuplicateColumns,
	QueryBuilder,
} from '../query-builders/index.ts';
import { RelationalQueryBuilder } from '../query-builders/query.ts';
import type { SelectedFields } from '../query-builders/select.types.ts';
import type {
	MySqlPreparedQueryConfig,
	MySqlQueryResultHKT,
	MySqlQueryResultKind,
	MySqlTransactionConfig,
} from '../session.ts';
import type { WithBuilder } from '../subquery.ts';
import type { MySqlTable } from '../table.ts';
import type { MySqlViewBase } from '../view-base.ts';
import type { MySqlView } from '../view.ts';
import { MySqlAsyncCountBuilder } from './count.ts';
import { MySqlAsyncDeleteBase } from './delete.ts';
import { MySqlAsyncInsertBase, type MySqlAsyncInsertHKT } from './insert.ts';
import { MySqlAsyncRelationalQuery, type MySqlAsyncRelationalQueryHKT } from './query.ts';
import { MySqlAsyncRaw } from './raw.ts';
import { MySqlAsyncSelectBase, type MySqlAsyncSelectBuilder } from './select.ts';
import type { MySqlAsyncSession, MySqlAsyncTransaction } from './session.ts';
import { MySqlAsyncUpdateBase, type MySqlAsyncUpdateHKT } from './update.ts';

export class MySqlAsyncDatabase<
	TQueryResult extends MySqlQueryResultHKT,
	TRelations extends AnyRelations = EmptyRelations,
> {
	static readonly [entityKind]: string = 'MySqlDatabase';
	static [Symbol.hasInstance](value: unknown): boolean {
		return is(value, this);
	}

	declare readonly _: {
		readonly relations: TRelations;
		readonly session: MySqlAsyncSession<TQueryResult, TRelations>;
	};

	// TO-DO: Figure out how to pass DrizzleTypeError without breaking withReplicas
	query: {
		[K in keyof TRelations]: RelationalQueryBuilder<
			TRelations,
			TRelations[K],
			MySqlAsyncRelationalQueryHKT
		>;
	};

	constructor(
		/** @internal */
		readonly dialect: MySqlDialect,
		/** @internal */
		readonly session: MySqlAsyncSession<any, any>,
		relations: TRelations,
	) {
		this._ = {
			relations,
			session,
		};
		this.query = {} as typeof this['query'];
		for (const [tableName, relation] of Object.entries(relations)) {
			(this.query as MySqlAsyncDatabase<
				TQueryResult,
				AnyRelations
			>['query'])[
				tableName
			] = new RelationalQueryBuilder(
				relations,
				relations[relation.name]!.table as MySqlTable | MySqlView,
				relation,
				dialect,
				session,
				MySqlAsyncRelationalQuery,
			);
		}

		this.$cache = { invalidate: async (_params: any) => {} };
	}

	/**
	 * Creates a subquery that defines a temporary named result set as a CTE.
	 *
	 * It is useful for breaking down complex queries into simpler parts and for reusing the result set in subsequent parts of the query.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/select#with-clause}
	 *
	 * @param alias The alias for the subquery.
	 *
	 * Failure to provide an alias will result in a DrizzleTypeError, preventing the subquery from being referenced in other queries.
	 *
	 * @example
	 *
	 * ```ts
	 * // Create a subquery with alias 'sq' and use it in the select query
	 * const sq = db.$with('sq').as(db.select().from(users).where(eq(users.id, 42)));
	 *
	 * const result = await db.with(sq).select().from(sq);
	 * ```
	 *
	 * To select arbitrary SQL values as fields in a CTE and reference them in other CTEs or in the main query, you need to add aliases to them:
	 *
	 * ```ts
	 * // Select an arbitrary SQL value as a field in a CTE and reference it in the main query
	 * const sq = db.$with('sq').as(db.select({
	 *   name: sql<string>`upper(${users.name})`.as('name'),
	 * })
	 * .from(users));
	 *
	 * const result = await db.with(sq).select({ name: sq.name }).from(sq);
	 * ```
	 */
	$with: WithBuilder = (alias: string, selection?: ColumnsSelection) => {
		const as = (
			qb:
				| TypedQueryBuilder<ColumnsSelection | undefined>
				| SQL
				| ((qb: QueryBuilder) => TypedQueryBuilder<ColumnsSelection | undefined> | SQL),
		) => {
			if (typeof qb === 'function') {
				qb = qb(new QueryBuilder(this.dialect));
			}

			const sql = qb.getSQL();
			return new Proxy(
				new WithSubquery(
					sql,
					selection ?? ('getSelectedFields' in qb ? qb.getSelectedFields() ?? {} : {}) as SelectedFields,
					alias,
					true,
				),
				new SelectionProxyHandler({ alias, sqlAliasedBehavior: 'alias', sqlBehavior: 'error' }),
			);
		};
		return { as };
	};

	$count(
		source: MySqlTable | MySqlViewBase | SQL | SQLWrapper,
		filters?: SQL<unknown>,
	) {
		return new MySqlAsyncCountBuilder({ source, filters, session: this.session, dialect: this.dialect });
	}

	$cache: { invalidate: Cache['onMutate'] };

	/**
	 * Incorporates a previously defined CTE (using `$with`) into the main query.
	 *
	 * This method allows the main query to reference a temporary named result set.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/select#with-clause}
	 *
	 * @param queries The CTEs to incorporate into the main query.
	 *
	 * @example
	 *
	 * ```ts
	 * // Define a subquery 'sq' as a CTE using $with
	 * const sq = db.$with('sq').as(db.select().from(users).where(eq(users.id, 42)));
	 *
	 * // Incorporate the CTE 'sq' into the main query and select from it
	 * const result = await db.with(sq).select().from(sq);
	 * ```
	 */
	with(...queries: WithSubquery[]) {
		const self = this;

		/**
		 * Creates a select query.
		 *
		 * Calling this method with no arguments will select all columns from the table. Pass a selection object to specify the columns you want to select.
		 *
		 * Use `.from()` method to specify which table to select from.
		 *
		 * See docs: {@link https://orm.drizzle.team/docs/select}
		 *
		 * @param fields The selection object.
		 *
		 * @example
		 *
		 * ```ts
		 * // Select all columns and all rows from the 'cars' table
		 * const allCars: Car[] = await db.select().from(cars);
		 *
		 * // Select specific columns and all rows from the 'cars' table
		 * const carsIdsAndBrands: { id: number; brand: string }[] = await db.select({
		 *   id: cars.id,
		 *   brand: cars.brand
		 * })
		 *   .from(cars);
		 * ```
		 *
		 * Like in SQL, you can use arbitrary expressions as selection fields, not just table columns:
		 *
		 * ```ts
		 * // Select specific columns along with expression and all rows from the 'cars' table
		 * const carsIdsAndLowerNames: { id: number; lowerBrand: string }[] = await db.select({
		 *   id: cars.id,
		 *   lowerBrand: sql<string>`lower(${cars.brand})`,
		 * })
		 *   .from(cars);
		 * ```
		 */
		function select(): MySqlAsyncSelectBuilder<undefined>;
		function select<TSelection extends SelectedFields>(
			fields: TSelection,
		): MySqlAsyncSelectBuilder<TSelection>;
		function select(fields?: SelectedFields): MySqlAsyncSelectBuilder<SelectedFields | undefined> {
			return new MySqlSelectBuilder({
				fields: fields ?? undefined,
				session: self.session,
				dialect: self.dialect,
				withList: queries,
			}, MySqlAsyncSelectBase);
		}

		/**
		 * Adds `distinct` expression to the select query.
		 *
		 * Calling this method will return only unique values. When multiple columns are selected, it returns rows with unique combinations of values in these columns.
		 *
		 * Use `.from()` method to specify which table to select from.
		 *
		 * See docs: {@link https://orm.drizzle.team/docs/select#distinct}
		 *
		 * @param fields The selection object.
		 *
		 * @example
		 * ```ts
		 * // Select all unique rows from the 'cars' table
		 * await db.selectDistinct()
		 *   .from(cars)
		 *   .orderBy(cars.id, cars.brand, cars.color);
		 *
		 * // Select all unique brands from the 'cars' table
		 * await db.selectDistinct({ brand: cars.brand })
		 *   .from(cars)
		 *   .orderBy(cars.brand);
		 * ```
		 */
		function selectDistinct(): MySqlAsyncSelectBuilder<undefined>;
		function selectDistinct<TSelection extends SelectedFields>(
			fields: TSelection,
		): MySqlAsyncSelectBuilder<TSelection>;
		function selectDistinct(
			fields?: SelectedFields,
		): MySqlAsyncSelectBuilder<SelectedFields | undefined> {
			return new MySqlSelectBuilder({
				fields: fields ?? undefined,
				session: self.session,
				dialect: self.dialect,
				withList: queries,
				distinct: true,
			}, MySqlAsyncSelectBase);
		}

		/**
		 * Creates an update query.
		 *
		 * Calling this method without `.where()` clause will update all rows in a table. The `.where()` clause specifies which rows should be updated.
		 *
		 * Use `.set()` method to specify which values to update.
		 *
		 * See docs: {@link https://orm.drizzle.team/docs/update}
		 *
		 * @param table The table to update.
		 *
		 * @example
		 *
		 * ```ts
		 * // Update all rows in the 'cars' table
		 * await db.update(cars).set({ color: 'red' });
		 *
		 * // Update rows with filters and conditions
		 * await db.update(cars).set({ color: 'red' }).where(eq(cars.brand, 'BMW'));
		 * ```
		 */
		function update<TTable extends MySqlTable>(
			table: TTable,
		): MySqlUpdateBuilder<TTable, TQueryResult, MySqlAsyncUpdateHKT> {
			return new MySqlUpdateBuilder(table, self.session, self.dialect, queries, MySqlAsyncUpdateBase);
		}

		/**
		 * Creates a delete query.
		 *
		 * Calling this method without `.where()` clause will delete all rows in a table. The `.where()` clause specifies which rows should be deleted.
		 *
		 * See docs: {@link https://orm.drizzle.team/docs/delete}
		 *
		 * @param table The table to delete from.
		 *
		 * @example
		 *
		 * ```ts
		 * // Delete all rows in the 'cars' table
		 * await db.delete(cars);
		 *
		 * // Delete rows with filters and conditions
		 * await db.delete(cars).where(eq(cars.color, 'green'));
		 * ```
		 */
		function delete_<TTable extends MySqlTable>(
			table: TTable,
		): MySqlAsyncDeleteBase<TTable, TQueryResult> {
			return new MySqlAsyncDeleteBase(table, self.session, self.dialect, queries);
		}

		return { select, selectDistinct, update, delete: delete_ };
	}

	/**
	 * Creates a select query.
	 *
	 * Calling this method with no arguments will select all columns from the table. Pass a selection object to specify the columns you want to select.
	 *
	 * Use `.from()` method to specify which table to select from.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/select}
	 *
	 * @param fields The selection object.
	 *
	 * @example
	 *
	 * ```ts
	 * // Select all columns and all rows from the 'cars' table
	 * const allCars: Car[] = await db.select().from(cars);
	 *
	 * // Select specific columns and all rows from the 'cars' table
	 * const carsIdsAndBrands: { id: number; brand: string }[] = await db.select({
	 *   id: cars.id,
	 *   brand: cars.brand
	 * })
	 *   .from(cars);
	 * ```
	 *
	 * Like in SQL, you can use arbitrary expressions as selection fields, not just table columns:
	 *
	 * ```ts
	 * // Select specific columns along with expression and all rows from the 'cars' table
	 * const carsIdsAndLowerNames: { id: number; lowerBrand: string }[] = await db.select({
	 *   id: cars.id,
	 *   lowerBrand: sql<string>`lower(${cars.brand})`,
	 * })
	 *   .from(cars);
	 * ```
	 */
	select(): MySqlAsyncSelectBuilder<undefined>;
	select<TSelection extends SelectedFields>(fields: TSelection): MySqlAsyncSelectBuilder<TSelection>;
	select(fields?: SelectedFields): MySqlAsyncSelectBuilder<SelectedFields | undefined> {
		return new MySqlSelectBuilder(
			{ fields: fields ?? undefined, session: this.session, dialect: this.dialect },
			MySqlAsyncSelectBase,
		);
	}

	/**
	 * Adds `distinct` expression to the select query.
	 *
	 * Calling this method will return only unique values. When multiple columns are selected, it returns rows with unique combinations of values in these columns.
	 *
	 * Use `.from()` method to specify which table to select from.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/select#distinct}
	 *
	 * @param fields The selection object.
	 *
	 * @example
	 * ```ts
	 * // Select all unique rows from the 'cars' table
	 * await db.selectDistinct()
	 *   .from(cars)
	 *   .orderBy(cars.id, cars.brand, cars.color);
	 *
	 * // Select all unique brands from the 'cars' table
	 * await db.selectDistinct({ brand: cars.brand })
	 *   .from(cars)
	 *   .orderBy(cars.brand);
	 * ```
	 */
	selectDistinct(): MySqlAsyncSelectBuilder<undefined>;
	selectDistinct<TSelection extends SelectedFields>(
		fields: TSelection,
	): MySqlAsyncSelectBuilder<TSelection>;
	selectDistinct(fields?: SelectedFields): MySqlAsyncSelectBuilder<SelectedFields | undefined> {
		return new MySqlSelectBuilder({
			fields: fields ?? undefined,
			session: this.session,
			dialect: this.dialect,
			distinct: true,
		}, MySqlAsyncSelectBase);
	}

	/**
	 * Creates an update query.
	 *
	 * Calling this method without `.where()` clause will update all rows in a table. The `.where()` clause specifies which rows should be updated.
	 *
	 * Use `.set()` method to specify which values to update.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/update}
	 *
	 * @param table The table to update.
	 *
	 * @example
	 *
	 * ```ts
	 * // Update all rows in the 'cars' table
	 * await db.update(cars).set({ color: 'red' });
	 *
	 * // Update rows with filters and conditions
	 * await db.update(cars).set({ color: 'red' }).where(eq(cars.brand, 'BMW'));
	 * ```
	 */
	update<TTable extends MySqlTable>(table: TTable): MySqlUpdateBuilder<TTable, TQueryResult, MySqlAsyncUpdateHKT> {
		return new MySqlUpdateBuilder(table, this.session, this.dialect, undefined, MySqlAsyncUpdateBase);
	}

	/**
	 * Creates an insert query.
	 *
	 * Calling this method will create new rows in a table. Use `.values()` method to specify which values to insert.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/insert}
	 *
	 * @param table The table to insert into.
	 *
	 * @example
	 *
	 * ```ts
	 * // Insert one row
	 * await db.insert(cars).values({ brand: 'BMW' });
	 *
	 * // Insert multiple rows
	 * await db.insert(cars).values([{ brand: 'BMW' }, { brand: 'Porsche' }]);
	 *
	 * // Insert only selected columns
	 * await db.insert(cars, 'brand', 'productionYear').values([{ brand: 'BMW', productionYear: 1995 }, { brand: 'Porsche', productionYear: 1989 }]);
	 * ```
	 */
	insert<
		TTable extends MySqlTable,
		TColumnList extends (keyof InferInsertModel<TTable>)[] = [],
		TRequiredKeys extends string = RequiredInsertKeys<TTable>,
	>(
		table: TTable,
		...columns: TColumnList extends [] ? []
			: IsNever<TRequiredKeys> extends true ? TColumnList & NoDuplicateColumns<TColumnList>
			: [TRequiredKeys] extends [TColumnList[number]] ? TColumnList & NoDuplicateColumns<TColumnList>
			: DrizzleTypeError<
				`Column selection is missing following required columns: ${JoinUnion<
					`"${Exclude<TRequiredKeys, TColumnList[number]>}"`,
					', '
				>}`
			>[]
	): MySqlInsertBuilder<TTable, TQueryResult, TColumnList extends [] ? 'all' : TColumnList, MySqlAsyncInsertHKT>;
	insert<TTable extends MySqlTable>(
		table: TTable,
		...columns: string[]
	): MySqlInsertBuilder<TTable, TQueryResult, 'all', MySqlAsyncInsertHKT> {
		return new MySqlInsertBuilder(
			table,
			this.session,
			this.dialect,
			columns.length ? columns : undefined,
			MySqlAsyncInsertBase,
		);
	}

	/**
	 * Creates a delete query.
	 *
	 * Calling this method without `.where()` clause will delete all rows in a table. The `.where()` clause specifies which rows should be deleted.
	 *
	 * See docs: {@link https://orm.drizzle.team/docs/delete}
	 *
	 * @param table The table to delete from.
	 *
	 * @example
	 *
	 * ```ts
	 * // Delete all rows in the 'cars' table
	 * await db.delete(cars);
	 *
	 * // Delete rows with filters and conditions
	 * await db.delete(cars).where(eq(cars.color, 'green'));
	 * ```
	 */
	delete<TTable extends MySqlTable>(table: TTable): MySqlAsyncDeleteBase<TTable, TQueryResult> {
		return new MySqlAsyncDeleteBase(table, this.session, this.dialect);
	}

	/**
	 * Executes raw SQL query, responding with rows as arrays of values
	 *
	 * Types assume single statement is executed per query
	 *
	 * @param query - SQL query to execute
	 * @param mode - `'arrays'`
	 *
	 * @example
	 * ```ts
	 * // [number, string][]
	 * const rows = await db.execute<[number, string]>(sql`select ${users.id}, ${users.name} from ${users}`, 'arrays');
	 * ```
	 */
	execute<TRow extends unknown[] = unknown[]>(
		query: SQLWrapper | string,
		mode: 'arrays',
	): MySqlAsyncRaw<TRow[]>;
	/**
	 * Executes raw SQL query, responding with rows as objects
	 *
	 * Types assume single statement is executed per query
	 *
	 * @param query - SQL query to execute
	 * @param mode - `'objects'`
	 *
	 * @example
	 * ```ts
	 * // { id: number; name: string }[]
	 * const rows = await db.execute<{ id: number; name: string }>(sql`select ${users.id}, ${users.name} from ${users}`, 'objects');
	 * ```
	 */
	execute<TRow extends Record<string, any> = Record<string, unknown>>(
		query: SQLWrapper | string,
		mode: 'objects',
	): MySqlAsyncRaw<TRow[]>;
	/**
	 * Executes raw SQL query, returning driver's raw response
	 *
	 * Row type argument defines the type of the response:
	 * - `'unknown'` (default) - any response of the driver
	 * - `never` - response of a statement that returns no rows
	 * - object shape - response with rows of given shape
	 *
	 * Typed call assumes single statement is executed per query
	 *
	 * @param query - SQL query to execute
	 * @param mode - `'raw'` (default)
	 *
	 * @example
	 * ```ts
	 * // Any response of the driver
	 * const response = await db.execute(sql`select * from ${users}`);
	 *
	 * // Response of a statement that returns no rows
	 * const updated = await db.execute<never>(sql`update ${users} set ${users.name} = ${'John'}`);
	 *
	 * // Response with rows of given shape
	 * const selected = await db.execute<{ id: number; name: string }>(sql`select ${users.id}, ${users.name} from ${users}`);
	 * ```
	 */
	execute<TRow extends Record<string, any> | 'unknown' = 'unknown'>(
		query: SQLWrapper | string,
		mode?: 'raw' | undefined,
	): MySqlAsyncRaw<MySqlQueryResultKind<TQueryResult, TRow>>;
	execute(
		query: SQLWrapper | string,
		mode?: 'raw' | 'objects' | 'arrays' | undefined,
	): unknown {
		const sequel = typeof query === 'string' ? sql.raw(query) : query.getSQL();
		const builtQuery = this.dialect.sqlToQuery(sequel);
		const prepared = this.session.prepareQuery<
			MySqlPreparedQueryConfig & { execute: unknown }
		>(builtQuery, mode ?? 'raw');
		return new MySqlAsyncRaw(prepared, sequel, builtQuery);
	}

	transaction<T>(
		transaction: (
			tx: MySqlAsyncTransaction<TQueryResult, TRelations>,
			config?: MySqlTransactionConfig,
		) => Promise<T>,
		config?: MySqlTransactionConfig,
	): Promise<T> {
		return this.session.transaction(transaction, config);
	}
}

export type MySQLWithReplicas<Q> = Q & {
	$replica: Q;
	/**
	 * @deprecated `withReplicas` db now defaults to using primary
	 *
	 * Use `db.$replica` to redirect query to replica
	 */
	$primary: Q;
	$replicas: Q[];
};

export const withReplicas = <
	HKT extends MySqlQueryResultHKT,
	TRelations extends AnyRelations,
	Q extends MySqlAsyncDatabase<HKT, TRelations>,
>(
	primary: Q,
	replicas: [Q, ...Q[]],
	getReplica: (replicas: Q[]) => Q = () => replicas[Math.floor(Math.random() * replicas.length)]!,
): MySQLWithReplicas<Q> => {
	return Object.create(primary, {
		$replica: { get: () => getReplica(replicas) },
		$primary: { value: primary },
		$replicas: { value: replicas },
	});
};
